// static
bool PageStubDispatch::Accept(
    Page* impl,
    mojo::Message* message) {
  switch (static_cast<messages::Page>(message->header()->name)) {
    case messages::Page::kSendAccountInfo: {
      DCHECK(message->is_serialized());
      internal::Page_SendAccountInfo_Params_Data* params =
          reinterpret_cast<internal::Page_SendAccountInfo_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.0
      bool success = true;
      AccountInfoPtr p_account_info{};
      Page_SendAccountInfo_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadAccountInfo(&p_account_info))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->SendAccountInfo(        
        std::move(p_account_info));
      return true;
    }
    case messages::Page::kSendScreenMode: {
      DCHECK(message->is_serialized());
      internal::Page_SendScreenMode_Params_Data* params =
          reinterpret_cast<internal::Page_SendScreenMode_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.1
      bool success = true;
      ScreenMode p_screen_mode{};
      Page_SendScreenMode_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadScreenMode(&p_screen_mode))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->SendScreenMode(        
        std::move(p_screen_mode));
      return true;
    }
  }
  return false;
}

